def file(root, name, data=b'generated payload'):
    target = root / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(data)
    return target


def zipped(root, name, members, compression=zipfile.ZIP_STORED):
    target = root / name
    target.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(target, 'w', compression=compression) as archive:
        for member, data in members: archive.writestr(member, data)
    return target


def game(root, path, ident, platform='nes', **extra):
    return dict(id=ident, title='Original title ' + ident, platform=platform,
                rom_path='/roms/' + path.relative_to(root).as_posix(), native_core='core',
                files=['/roms/' + path.relative_to(root).as_posix()], **extra)


def audit(tmp_path, records, **options):
    root = tmp_path / 'roms'; root.mkdir(exist_ok=True)
    cache = Cache(tmp_path / 'cache.sqlite')
    try: return Auditor(root, cache, rate_mib=0, **options).run(records)
    finally: cache.close()


def test_single_cartridge_cross_zip_raw_and_compression_with_exact_evidence(tmp_path):
    root = tmp_path / 'roms'; data = b'cartridge contents' * 200
    raw = file(root, 'one/Game (USA).nes', data)
    first = zipped(root, 'two/game.zip', [('Chinese name.nes', data)])
    second = zipped(root, 'three/game.zip', [('folder/Other name.nes', data)], zipfile.ZIP_DEFLATED)
    report = audit(tmp_path, [game(root, p, str(i)) for i, p in enumerate((raw, first, second))])
    assert len(report['duplicates']['content_exact']) == 1
    group = report['duplicates']['content_exact'][0]
    assert group['game_ids'] == ['0', '1', '2'] and group['auto_merge_safe']
    assert group['sha256'] == hashlib.sha256(data).hexdigest()
    assert not group['automatic_file_deletion_allowed']
    assert not report['duplicates']['raw_exact']
    for entry in report['games']:
        assert entry['raw']['status'] == 'verified'
        assert len(entry['source_manifest'][0]['raw_sha256']) == 64
        assert entry['entry_signature'] and str(root) not in json.dumps(entry)
    assert report['games'][0]['filename_labels'] == [{'kind': 'region', 'evidence': '(USA)'}]


def test_sidecar_inside_zip_prevents_cartridge_collapse_and_is_hashed(tmp_path):
    root = tmp_path / 'roms'; data = b'cartridge'
    paths = [zipped(root, 'a/game.zip', [('game.nes', data), ('game.ips', b'patch A')]),
             zipped(root, 'b/game.zip', [('game.nes', data), ('game.ips', b'patch B')]),
             file(root, 'c/game.nes', data)]
    report = audit(tmp_path, [game(root, p, str(i)) for i, p in enumerate(paths)])
    assert not report['duplicates']['content_exact']
    assert report['games'][0]['content']['kind'] == 'zip_tree'
    assert len(report['games'][0]['zip_members']) == 2
    assert report['games'][2]['content']['reason'] == 'unique_size_or_layout'


def test_collection_discovery_lists_directory_once_and_keeps_sidecars(tmp_path, monkeypatch):
    root = tmp_path / 'roms'
    paths = [file(root, f'collection/game{i}.nes') for i in range(40)]
    # Same-stem catalog ROMs are not sidecars; unowned patches and directories are.
    paths.append(zipped(root, 'collection/game0.zip', [('same.nes', b'generated payload')]))
    file(root, 'collection/GAME1.IPS', b'patch')
    (root / 'collection/game2').mkdir()
    listed = []
    original = Path.iterdir
    def tracked(directory):
        listed.append(directory)
        return original(directory)
    monkeypatch.setattr(Path, 'iterdir', tracked)
    report = audit(tmp_path, [game(root, path, str(i)) for i, path in enumerate(paths)], hash_all=True)
    assert listed == [root / 'collection']
    assert report['games'][0]['content']['status'] == 'verified'
    assert all(report['games'][i]['unverified'][0]['code'] == 'adjacent_resources' for i in (1, 2))
    assert all(report['games'][i]['content']['status'] != 'verified' for i in (1, 2))


def test_discovery_sidecar_cache_refreshes_when_directory_changes(tmp_path):
    root = tmp_path / 'roms'
    primary = file(root, 'collection/game.nes')
    with closing(Cache(tmp_path / 'cache.sqlite')) as cache:
        auditor = Auditor(root, cache, rate_mib=0)
        auditor.catalog_sources = {primary}
        assert not auditor.has_sidecars(primary)
        before = primary.parent.stat()
        patch = file(root, 'collection/Game.bps', b'patch')
        os.utime(primary.parent, ns=(before.st_atime_ns, before.st_mtime_ns + 1_000_000))
        assert auditor.has_sidecars(primary)
        patch.unlink()
        assert not auditor.has_sidecars(primary)
        # A new catalog inventory must reset ownership even without file changes.
        extra = file(root, 'collection/game.zip')
        auditor.run([game(root, primary, 'a'), game(root, extra, 'b')])
        result = auditor.run([game(root, primary, 'a')])
        assert result['games'][0]['unverified'][0]['code'] == 'adjacent_resources'


