def test_zip_symlink_case_collision_and_empty_directory_are_not_single_cartridge(tmp_path):
    root = tmp_path / 'roms'; root.mkdir()
    link = zipfile.ZipInfo('game.nes'); link.create_system = 3
    link.external_attr = (stat.S_IFLNK | 0o777) << 16
    path = root / 'link.zip'
    with zipfile.ZipFile(path, 'w') as archive: archive.writestr(link, '../../outside')
    colliding = zipped(root, 'collision.zip', [('Game.nes', b'a'), ('game.nes', b'b')])
    emptydir = zipped(root, 'emptydir.zip', [('game.nes', b'a'), ('extra/', b'')])
    report = audit(tmp_path, [game(root, p, str(i)) for i, p in enumerate((path, colliding, emptydir))], hash_all=True)
    assert report['games'][0]['errors'][0]['code'] == 'zip_special_file'
    assert report['games'][1]['unverified'][0]['code'] == 'ambiguous_zip_names'
    assert report['games'][2]['content']['kind'] == 'zip_tree'


def test_zip_limits_and_crc_corruption_are_distinct(tmp_path):
    root = tmp_path / 'roms'
    limited = zipped(root, 'limit.zip', [('game.nes', b'x' * 100)])
    report = audit(tmp_path, [game(root, limited, 'a')], hash_all=True, max_zip_bytes=10)
    assert report['games'][0]['unverified'][0]['code'] == 'zip_expansion_limit'
    corrupt = zipped(root, 'corrupt.zip', [('game.nes', b'PAYLOAD')])
    raw = corrupt.read_bytes(); corrupt.write_bytes(raw.replace(b'PAYLOAD', b'BROKEN!'))
    report = audit(tmp_path, [game(root, corrupt, 'a')], hash_all=True)
    assert report['games'][0]['content']['status'] == 'error'
    assert any(e['code'] == 'invalid_zip' for e in report['games'][0]['errors'])
    assert report['games'][0]['raw']['status'] == 'verified'


@pytest.mark.parametrize('resolved', ['新石中劍.bin', '../escape.bin'])
def test_zip_unicode_path_uses_exact_zipinfo_and_checks_both_names(tmp_path, monkeypatch, resolved):
    # Emulate Python 3.13's valid Unicode Path extra handling on older test hosts.
    # Header/orig_filename remains legacy.bin; filename/NameToInfo is Unicode.
    import zlib
    root = tmp_path / 'roms'
    root.mkdir()
    path = root / 'unicode.zip'
    data = b'generated cartridge'
    extra = b'\x01' + struct.pack('<I', zlib.crc32(b'legacy.bin')) + resolved.encode()
    info = zipfile.ZipInfo('legacy.bin')
    info.extra = struct.pack('<HH', 0x7075, len(extra)) + extra
    with zipfile.ZipFile(path, 'w') as archive:
        archive.writestr(info, data)
    actual_zip = zipfile.ZipFile
    class UnicodeZip(actual_zip):
        def __init__(self, *args, **kwargs):
            super().__init__(*args, **kwargs)
            for entry in self.filelist:
                self.NameToInfo.pop(entry.filename)
                entry.filename = resolved
                self.NameToInfo[resolved] = entry
    monkeypatch.setattr(zipfile, 'ZipFile', UnicodeZip)
    report = audit(tmp_path, [game(root, path, 'a', 'megadrive')], hash_all=True)
    if resolved.startswith('../'):
        assert report['games'][0]['errors'][0]['code'] == 'unsafe_zip_path'
        assert report['games'][0]['content']['status'] != 'verified'
    else:
        assert report['games'][0]['content']['sha256'] == hashlib.sha256(data).hexdigest()
        assert not report['games'][0]['errors']


