def test_cache_reuses_full_hash_and_invalidates_same_size_preserved_mtime(tmp_path):
    root = tmp_path / 'roms'; a = file(root, 'a.nes', b'AAAA'); b = file(root, 'b.nes', b'AAAA')
    records = [game(root, a, 'a'), game(root, b, 'b')]
    first = audit(tmp_path, records); second = audit(tmp_path, records)
    assert second['progress']['bytes_hashed'] == 0 and second['progress']['cache_hits']
    old = b.stat(); b.write_bytes(b'BBBB'); os.utime(b, ns=(old.st_atime_ns, old.st_mtime_ns))
    third = audit(tmp_path, records)
    assert not third['duplicates']['content_exact']
    assert third['progress']['bytes_hashed'] == 4
    assert first['games'][1]['entry_signature'] != third['games'][1]['entry_signature']


@pytest.fixture
def small_samples(monkeypatch):
    monkeypatch.setattr(audit_module, 'RAW_SAMPLE_MIN_BYTES', 1024)
    monkeypatch.setattr(audit_module, 'RAW_SAMPLE_BYTES', 64)
    return 3 * 64


def opaque_games(tmp_path, payloads, suffix='.iso', platform='ps2'):
    root = tmp_path / 'roms'
    return [game(root, file(root, f'{index}{suffix}', data), str(index), platform)
            for index, data in enumerate(payloads)]


@pytest.mark.parametrize('offset', [0, (4096 - 64) // 2, 4096 - 64])
def test_raw_sample_difference_excludes_without_claiming_full_hash(tmp_path, small_samples, offset):
    data = bytearray(b'A' * 4096)
    data[offset] = ord('B')
    records = opaque_games(tmp_path, [b'A' * 4096, data])
    report = audit(tmp_path, records)
    assert report['completed']
    assert report['progress']['bytes_hashed'] == 2 * small_samples
    assert report['progress']['bytes_sampled'] == 2 * small_samples
    assert report['read_budget']['actual_full_hash_input_bytes'] == 0
    assert report['summary']['raw_verified'] == 0
    assert report['summary']['raw_sample_excluded_games'] == 2
    assert not report['duplicates']['raw_exact']
    for entry in report['games']:
        assert entry['raw'] == dict(status='not_hashed', reason='distinct_raw_sample')
        assert not entry['raw_sample']['whole_file_verified']
        assert 'raw_sha256' not in entry['source_manifest'][0]
    repeated = audit(tmp_path, records)
    assert repeated['progress']['bytes_hashed'] == 0
    assert repeated['progress']['sample_bytes_from_cache'] == 2 * small_samples
    assert repeated['summary']['raw_verified'] == 0


def test_matching_samples_still_hash_unsampled_bytes_and_never_auto_merge(tmp_path, small_samples):
    changed = bytearray(b'A' * 4096)
    changed[1000] = ord('B')  # Outside all sampled ranges.
    report = audit(tmp_path, opaque_games(tmp_path, [b'A' * 4096, changed, b'A' * 4096]))
    assert report['progress']['bytes_hashed'] == 3 * (4096 + small_samples)
    assert report['summary']['raw_verified'] == 3
    assert report['summary']['raw_sample_excluded_games'] == 0
    assert report['duplicates']['raw_exact'][0]['game_ids'] == ['0', '2']
    assert not report['duplicates']['raw_exact'][0]['auto_merge_safe']
    assert not report['duplicates']['content_exact']


def test_partial_sample_budget_is_counted_but_not_cached_and_resume_completes(tmp_path, small_samples):
    records = opaque_games(tmp_path, [b'A' * 4096, b'B' * 4096])
    first = audit(tmp_path, records, max_read_bytes=small_samples + 1)
    assert not first['completed']
    assert first['progress']['bytes_hashed'] == first['progress']['bytes_sampled'] == small_samples + 1
    assert first['progress']['files_sampled'] == 1
    assert first['summary']['raw_verified'] == 0
    assert first['summary']['raw_sample_excluded_games'] == 0
    resumed = audit(tmp_path, records, max_read_bytes=small_samples)
    assert resumed['completed']
    assert resumed['progress']['sample_cache_hits'] == 1
    assert resumed['progress']['bytes_sampled'] == small_samples
    assert resumed['summary']['raw_sample_excluded_games'] == 2


def test_finish_unit_sampling_and_full_hash_make_progress_across_tiny_batches(tmp_path, small_samples):
    records = opaque_games(tmp_path, [b'A' * 4096, b'A' * 4096])
    reports = [audit(tmp_path, records, max_read_bytes=100, finish_unit=True) for _ in range(4)]
    assert [report['completed'] for report in reports] == [False, False, False, True]
    assert [report['progress']['bytes_hashed'] for report in reports] == [small_samples, small_samples, 4096, 4096]
    assert all(report['summary']['raw_verified'] < 2 for report in reports[:-1])
    assert reports[-1]['summary']['raw_verified'] == 2
    assert reports[-1]['duplicates']['raw_exact'][0]['game_ids'] == ['0', '1']


def test_sample_cache_invalidates_same_size_preserved_mtime(tmp_path, small_samples):
    records = opaque_games(tmp_path, [b'A' * 4096, b'B' * 4096])
    audit(tmp_path, records)
    second = tmp_path / 'roms/1.iso'
    old = second.stat()
    second.write_bytes(b'A' * 4096)
    os.utime(second, ns=(old.st_atime_ns, old.st_mtime_ns))
    result = audit(tmp_path, records)
    assert result['progress']['sample_cache_hits'] == 1
    assert result['progress']['bytes_sampled'] == small_samples
    assert result['summary']['raw_verified'] == 2
