def test_source_changes_during_sampling_never_cache_or_prune_group(tmp_path, small_samples, monkeypatch):
    records = opaque_games(tmp_path, [b'A' * 4096, b'B' * 4096])
    original = Progress.read
    changed = False
    def read_and_change(progress, stream, maximum=audit_module.CHUNK, **kwargs):
        nonlocal changed
        value = original(progress, stream, maximum, **kwargs)
        if kwargs.get('sample') and not changed:
            changed = True
            (tmp_path / 'roms/0.iso').write_bytes(b'C' * 4096)
        return value
    monkeypatch.setattr(Progress, 'read', read_and_change)
    result = audit(tmp_path, records)
    assert result['games'][0]['raw']['status'] == 'error'
    assert any(error['code'] == 'source_changed' for error in result['games'][0]['errors'])
    assert result['progress']['files_sampled'] == 1
    assert result['summary']['raw_sample_excluded_games'] == 0
    assert not result['duplicates']['raw_exact']


def test_source_change_after_sampling_invalidates_other_exclusions(tmp_path, small_samples, monkeypatch):
    records = opaque_games(tmp_path, [b'A' * 4096, b'B' * 4096])
    original = Auditor.sample_raw_group
    def compare_then_change(auditor, group, targets):
        result = original(auditor, group, targets)
        (tmp_path / 'roms/1.iso').write_bytes(b'A' * 4096)
        return result
    monkeypatch.setattr(Auditor, 'sample_raw_group', compare_then_change)
    result = audit(tmp_path, records)
    assert result['games'][0]['raw']['reason'] == 'sample_comparison_source_changed'
    assert result['games'][1]['raw']['status'] == 'error'
    assert result['progress']['raw_sample_excluded_games'] == 0
    assert result['progress']['raw_sample_saved_bytes'] == 0


@pytest.mark.parametrize('case', ['hash_all', 'small', 'cartridge', 'zip', 'mixed', 'directory'])
def test_sampling_never_shortcuts_hash_all_decoded_or_small_sources(tmp_path, small_samples, case):
    root = tmp_path / 'roms'
    options = {}
    if case == 'small':
        records = opaque_games(tmp_path, [b'A' * 512, b'B' * 512])
    elif case == 'cartridge':
        records = opaque_games(tmp_path, [b'A' * 4096, b'B' * 4096], '.nes', 'nes')
    elif case in ('zip', 'mixed'):
        first = zipped(root, 'a.zip', [('game.nes', b'A' * 4096)])
        second = file(root, 'b.' + ('zip' if case == 'zip' else '7z'), first.read_bytes())
        records = [game(root, path, str(index)) for index, path in enumerate((first, second))]
    elif case == 'directory':
        records = [game(root, file(root, f'{index}/game.iso', b'A' * 4096), str(index), 'ps2',
                        resource_root='/roms/' + str(index)) for index in range(2)]
    else:
        records = opaque_games(tmp_path, [b'A' * 4096, b'B' * 4096])
        options['hash_all'] = True
    result = audit(tmp_path, records, **options)
    assert result['progress']['bytes_sampled'] == 0
    assert result['summary']['raw_verified'] == 2
    assert all('raw_sample' not in entry for entry in result['games'])


