    executable = file(root, 'game/main.exe', b'x')
    file(root, 'game/data.dat', b'D' * 4096)
    records = [game(root, executable, 'pc', 'windows', resource_root='/roms/game'),
               game(root, file(root, 'small.iso', b'S' * 512), 'small', 'psp')]
