def test_default_hard_budget_remains_strict_for_an_oversized_file(tmp_path):
    root = tmp_path / 'roms'
    records = [game(root, file(root, 'a.nes', b'123456789'), 'a')]
    for _ in range(2):
        report = audit(tmp_path, records, hash_all=True, max_read_bytes=5)
        assert not report['completed'] and report['progress']['bytes_hashed'] == 5
        assert report['progress']['files_hashed'] == 0
        assert report['read_budget']['policy'] == 'hard' and report['read_budget']['overrun_bytes'] == 0
        assert not report['progress']['cache_hits']


def test_cli_finish_unit_reports_actual_bytes_over_batch_budget(tmp_path):
    root = tmp_path / 'roms'
    records = [game(root, file(root, 'game.nes', b'123456789'), 'a')]
    catalog = tmp_path / 'catalog.json'; catalog.write_text(json.dumps(records))
    output = tmp_path / 'report.json'
    result = main(['--catalog', str(catalog), '--rom-root', str(root),
                   '--cache', str(tmp_path / 'cache.sqlite'), '--output', str(output),
                   '--hash-all', '--max-read-gib', str(5 / 1024**3), '--finish-unit', '--rate-mib', '0'])
    report = json.loads(output.read_text())
    assert result == 0 and report['completed']
    assert report['read_budget']['policy'] == 'finish_unit'
    assert report['read_budget']['limit_bytes'] == 5
    assert report['read_budget']['actual_hash_bytes'] == 9
    assert report['read_budget']['overrun_bytes'] == 4


def test_unique_size_not_claimed_hashed_and_unknown_archive_still_raw_comparable(tmp_path):
    root = tmp_path / 'roms'
    a = file(root, 'a.7z', b'opaque archive bytes'); b = file(root, 'b.7z', a.read_bytes())
    unique = file(root, 'unique.iso', b'larger unique size' * 10)
    report = audit(tmp_path, [game(root, a, 'a', 'ps2'), game(root, b, 'b', 'ps2'), game(root, unique, 'c', 'ps2')])
    assert report['duplicates']['raw_exact'][0]['game_ids'] == ['a', 'b']
    assert not report['duplicates']['content_exact']
    assert report['games'][2]['raw'] == {'status': 'not_hashed', 'reason': 'unique_size_or_layout'}
    assert 'raw_sha256' not in report['games'][2]['source_manifest'][0]


def test_arcade_and_different_core_context_are_not_safe_merges(tmp_path):
    root = tmp_path / 'roms'
    a = zipped(root, 'a.zip', [('set.bin', b'arcade rom')]); b = file(root, 'b.zip', a.read_bytes())
    records = [game(root, a, 'a', 'fbneo'), game(root, b, 'b', 'fbneo')]
    records[1]['native_core'] = 'different-core'
    report = audit(tmp_path, records)
    for groups in report['duplicates'].values():
        group = groups[0]
        assert not group['auto_merge_safe'] and group['runtime_context_mismatch']
        assert 'dependencies_unverified' in group['merge_blocking_reasons']


def test_path_escape_symlink_and_adjacent_patch_are_unverified(tmp_path):
    root = tmp_path / 'roms'; source = file(root, 'game.nes'); file(root, 'game.ips', b'patch')
    outside = file(tmp_path, 'outside.nes')
    (root / 'linked.nes').symlink_to(outside)
    records = [game(root, source, 'a'), dict(id='b', title='b', platform='nes', rom_path=str(outside)),
               dict(id='c', title='c', platform='nes', rom_path='/roms/linked.nes')]
    report = audit(tmp_path, records, hash_all=True)
    assert report['games'][0]['unverified'][0]['code'] == 'adjacent_resources'
    assert report['games'][1]['errors'][0]['code'] == 'outside_rom_root'
    assert report['games'][2]['unverified'][0]['code'] == 'source_symlink'
    assert not report['progress']['bytes_hashed']


def test_explicit_filename_labels_do_not_guess_translation(tmp_path):
    assert filename_labels('中文游戏名称.nes') == []
    tags = filename_labels('Game (Japan) (Rev 2) [T+Eng] [Hack].zip')
    assert {t['kind'] for t in tags} == {'region', 'revision', 'translation', 'variant'}
    assert filename_labels('某游戏 汉化版.chd') == [{'kind': 'translation', 'evidence': '汉化版'}]


def test_forged_zip_member_count_rejected_before_unbounded_allocation(tmp_path):
    root = tmp_path / 'roms'
    path = zipped(root, 'game.zip', [('a.nes', b'a'), ('b.nes', b'b')])
    data = bytearray(path.read_bytes()); offset = data.rfind(b'PK\x05\x06')
    struct.pack_into('<HH', data, offset + 8, 1, 1)
    path.write_bytes(data)
    report = audit(tmp_path, [game(root, path, 'a')], hash_all=True)
    assert report['games'][0]['errors'][0]['code'] == 'invalid_zip'
    assert not report['progress']['zip_members_hashed']


def test_cli_platform_filter_output_locations_and_spreadsheet_escape(tmp_path):
    root = tmp_path / 'roms'
    records = [game(root, file(root, 'a.nes'), 'a'), game(root, file(root, 'b.gb'), 'b', 'gb')]
    records[0]['title'] = '=unsafe-formula'
    catalog = tmp_path / 'catalog.json'; catalog.write_text(json.dumps({'games': records, 'path_prefix': '/roms'}))
    args = ['--catalog', str(catalog), '--rom-root', str(root), '--cache', str(tmp_path / 'cache.sqlite'),
            '--output', str(tmp_path / 'report.json'), '--platform', 'nes', '--rate-mib', '0', '--hash-all']
    assert main(args) == 0
    report = json.loads((tmp_path / 'report.json').read_text())
    assert report['summary']['games'] == 1 and report['games'][0]['title'] == '=unsafe-formula'
    with (tmp_path / 'report.csv').open(encoding='utf-8-sig') as source:
        assert next(csv.DictReader(source))['title'] == "'=unsafe-formula"
    args[args.index('--output') + 1] = str(root / 'report.json')
    with pytest.raises(SystemExit): main(args)


def test_cache_concurrent_process_guard(tmp_path):
    cache = Cache(tmp_path / 'cache.sqlite')
    try:
        with pytest.raises(ValueError, match='Another audit'): Cache(tmp_path / 'cache.sqlite')
    finally: cache.close()
